add({id:'pafi',c:'Neumología',t:'Índice de oxigenación (presión arterial de oxígeno entre fracción inspirada)',s:'Gravedad del síndrome de dificultad respiratoria aguda',f:[n('pao2','Presión arterial de oxígeno','milímetros de mercurio'),n('fio2','Fracción inspirada de oxígeno','por ciento',{ph:'21 en aire ambiente'})],
  r:v=>{const x=v.pao2/(v.fio2/100);return{n:r0(x),u:'',i:x>300?'Mayor de 300: sin criterio de síndrome de dificultad respiratoria aguda':x>200?'201 a 300: leve':x>100?'101 a 200: moderado':'100 o menos: grave',c:x>300?'ok':x>200?'warn':'bad',d:'La definición de Berlín exige además presión positiva al final de la espiración de 5 o más, inicio en una semana e infiltrados bilaterales no explicados por falla cardiaca.'}},
  ref:['ARDS Definition Task Force; Ranieri VM, Rubenfeld GD, et al. Acute respiratory distress syndrome: the Berlin Definition. JAMA. 2012;307(23):2526-2533.']});
add({id:'gaa',c:'Neumología',t:'Gradiente alvéolo-arterial de oxígeno',s:'Diferencia entre oxígeno alveolar y arterial',f:[n('pao2','Presión arterial de oxígeno','milímetros de mercurio'),n('paco2','Presión arterial de dióxido de carbono','milímetros de mercurio'),n('fio2','Fracción inspirada de oxígeno','por ciento',{ph:'21'}),n('patm','Presión atmosférica','milímetros de mercurio',{ph:'760 a nivel del mar',opt:1}),EDAD],
  r:v=>{const pa=(v.patm||760),A=(v.fio2/100)*(pa-47)-v.paco2/0.8,g=A-v.pao2,esp=v.edad/4+4;return{n:r0(g)+' milímetros de mercurio',u:`Oxígeno alveolar ${r0(A)}`,i:g>esp?`Aumentado (esperado para la edad hasta ${r0(esp)}): sugiere alteración de la ventilación-perfusión, cortocircuito o difusión`:'Normal para la edad: si hay hipoxemia, pensar en hipoventilación o baja presión inspirada',c:g>esp?'warn':'ok'}},
  ref:['West JB, Luks AM. West\'s Respiratory Physiology: The Essentials. 11.ª edición. Wolters Kluwer; 2021.']});
add(esc('stopbang','Neumología','Cuestionario STOP-Bang','Riesgo de apnea obstructiva del sueño',[
  c('s','Ronca fuerte'),c('t','Cansancio o somnolencia durante el día'),c('o','Le han observado pausas respiratorias al dormir'),c('p','Hipertensión arterial'),c('b','Índice de masa corporal mayor de 35'),c('a','Edad mayor de 50 años'),c('n','Circunferencia de cuello mayor de 40 centímetros'),c('g','Sexo masculino')],
  [[2,'0 a 2: riesgo bajo','ok'],[4,'3 a 4: riesgo intermedio','warn'],[8,'5 a 8: riesgo alto','bad']],
  ['Chung F, Yegneswaran B, Liao P, et al. STOP questionnaire: a tool to screen patients for obstructive sleep apnea. Anesthesiology. 2008;108(5):812-821.','Chung F, Subramanyam R, Liao P, et al. High STOP-Bang score indicates a high probability of obstructive sleep apnoea. Br J Anaesth. 2012;108(5):768-775.']));
add({id:'paqano',c:'Neumología',t:'Índice tabáquico',s:'Paquetes-año',f:[n('cig','Cigarros al día',''),n('a','Años fumando','')],
  r:v=>{const x=v.cig*v.a/20;return{n:r1(x),u:'paquetes-año',i:x>=20?'20 o más: riesgo alto de enfermedad pulmonar obstructiva crónica':x>=10?'10 a 19: riesgo moderado':'Menos de 10',c:x>=20?'bad':x>=10?'warn':'ok'}},
  ref:['Prignot J. Quantification and chemical markers of tobacco-exposure. Eur J Respir Dis. 1987;70(1):1-7.']});

/* GASTROENTEROLOGÍA */
add(esc('childpugh','Gastroenterología','Clasificación de Child-Pugh','Función hepática en cirrosis',[
  s('b','Bilirrubina total (miligramos por decilitro)',[['Menor de 2',1],['2 a 3',2],['Mayor de 3',3]]),
  s('a','Albúmina (gramos por decilitro)',[['Mayor de 3.5',1],['2.8 a 3.5',2],['Menor de 2.8',3]]),
  s('i','Razón internacional normalizada',[['Menor de 1.7',1],['1.7 a 2.3',2],['Mayor de 2.3',3]]),
  s('as','Ascitis',[['Ausente',1],['Leve o controlada con diurético',2],['Moderada a grave o refractaria',3]]),
  s('e','Encefalopatía',[['Ausente',1],['Grado 1 a 2',2],['Grado 3 a 4',3]])],
  [[6,'Clase A (5 a 6): enfermedad compensada','ok'],[9,'Clase B (7 a 9): compromiso funcional significativo','warn'],[15,'Clase C (10 a 15): enfermedad descompensada','bad']],
  ['Pugh RN, Murray-Lyon IM, Dawson JL, et al. Transection of the oesophagus for bleeding oesophageal varices. Br J Surg. 1973;60(8):646-649.']));
add({id:'meld3',c:'Gastroenterología',t:'MELD 3.0',s:'Modelo para la enfermedad hepática terminal, versión 2021',f:[SEXO,n('bili','Bilirrubina total','miligramos por decilitro'),n('cr','Creatinina','miligramos por decilitro'),n('inr','Razón internacional normalizada',''),n('na','Sodio','miliequivalentes por litro'),n('alb','Albúmina','gramos por decilitro'),c('dial','Diálisis 2 o más veces en la última semana')],
  r:v=>{const cl=(x,a,b)=>Math.min(b,Math.max(a,x));const B=Math.max(1,v.bili),I=Math.max(1,v.inr),C=v.dial?3:cl(v.cr,1,3),N=cl(v.na,125,137),Al=cl(v.alb,1.5,3.5);
    const m=r0((v.sexo==='M'?1.33:0)+4.56*Math.log(B)+0.82*(137-N)-0.24*(137-N)*Math.log(B)+9.09*Math.log(I)+11.14*Math.log(C)+1.85*(3.5-Al)-1.83*(3.5-Al)*Math.log(C)+6);
    const sv=100*Math.pow(0.946,Math.exp(0.17698*m-3.56));return{n:m,u:'puntos',i:`Supervivencia estimada a 90 días: ${r1(sv)}%`,c:m>=30?'bad':m>=20?'warn':'ok'}},
  ref:['Kim WR, Mannalithara A, Heimbach JK, et al. MELD 3.0: The Model for End-Stage Liver Disease Updated for the Modern Era. Gastroenterology. 2021;161(6):1887-1895.']});
add({id:'meldna',c:'Gastroenterología',t:'MELD con sodio',s:'Modelo para la enfermedad hepática terminal con sodio',f:[n('bili','Bilirrubina total','miligramos por decilitro'),n('cr','Creatinina','miligramos por decilitro'),n('inr','Razón internacional normalizada',''),n('na','Sodio','miliequivalentes por litro'),c('dial','Diálisis 2 o más veces en la última semana')],
  r:v=>{const C=v.dial?4:Math.min(4,Math.max(1,v.cr)),B=Math.max(1,v.bili),I=Math.max(1,v.inr),N=Math.min(137,Math.max(125,v.na));let m=Math.round((0.957*Math.log(C)+0.378*Math.log(B)+1.120*Math.log(I)+0.643)*10*10)/10;
    if(m>11)m=m+1.32*(137-N)-0.033*m*(137-N);m=Math.min(40,r0(m));return{n:m,u:'puntos',i:m>=30?'Mortalidad a 3 meses muy alta':m>=20?'Mortalidad a 3 meses alta':m>=10?'Mortalidad a 3 meses intermedia':'Mortalidad a 3 meses baja',c:m>=20?'bad':m>=10?'warn':'ok'}},
  ref:['Kim WR, Biggins SW, Kremers WK, et al. Hyponatremia and mortality among patients on the liver-transplant waiting list. N Engl J Med. 2008;359(10):1018-1026.']});
add({id:'blatchford',c:'Gastroenterología',t:'Escala de Glasgow-Blatchford',s:'Hemorragia de tubo digestivo alto',f:[SEXO,n('bun','Nitrógeno ureico en sangre','miligramos por decilitro'),n('hb','Hemoglobina','gramos por decilitro'),n('pas','Presión arterial sistólica','milímetros de mercurio'),c('fc','Frecuencia cardiaca de 100 o más'),c('mel','Melena'),c('sin','Síncope',2),c('hep','Enfermedad hepática',2),c('ic','Insuficiencia cardiaca',2)],
  r:v=>{const u=v.bun*0.357;let x=u>=25?6:u>=10?4:u>=8?3:u>=6.5?2:0;const H=v.hb;x+=v.sexo==='H'?(H<10?6:H<12?3:H<13?1:0):(H<10?6:H<12?1:0);x+=v.pas<90?3:v.pas<100?2:v.pas<110?1:0;x+=(v.fc?1:0)+(v.mel?1:0)+(v.sin?2:0)+(v.hep?2:0)+(v.ic?2:0);
    return{n:x,u:'puntos',i:x<=1?'0 a 1: riesgo muy bajo; puede considerarse manejo ambulatorio':'2 o más: requiere hospitalización y endoscopia',c:x<=1?'ok':x>=7?'bad':'warn'}},
  ref:['Blatchford O, Murray WR, Blatchford M. A risk score to predict need for treatment for upper-gastrointestinal haemorrhage. Lancet. 2000;356(9238):1318-1321.','Gralnek IM, Stanley AJ, Morris AJ, et al. Endoscopic diagnosis and management of nonvariceal upper gastrointestinal hemorrhage: ESGE Guideline update 2021. Endoscopy. 2021;53(3):300-332.']});
add(esc('bisap','Gastroenterología','Escala BISAP','Mortalidad en pancreatitis aguda',[c('b','Nitrógeno ureico mayor de 25 miligramos por decilitro'),c('i','Alteración del estado mental'),c('s','Síndrome de respuesta inflamatoria sistémica'),c('a','Edad mayor de 60 años'),c('p','Derrame pleural')],
  [[2,'0 a 2: mortalidad baja (menor de 2%)','ok'],[5,'3 a 5: mortalidad aumentada (5 a 20%)','bad']],
  ['Wu BU, Johannes RS, Sun X, et al. The early prediction of mortality in acute pancreatitis: a large population-based study. Gut. 2008;57(12):1698-1703.']));
add({id:'gasa',c:'Gastroenterología',t:'Gradiente de albúmina suero-ascitis',s:'Origen de la ascitis',f:[n('as','Albúmina sérica','gramos por decilitro'),n('aa','Albúmina en líquido de ascitis','gramos por decilitro')],
  r:v=>{const x=v.as-v.aa;return{n:r1(x),u:'gramos por decilitro',i:x>=1.1?'1.1 o más: ascitis por hipertensión portal (cirrosis, insuficiencia cardiaca, trombosis)':'Menor de 1.1: sin hipertensión portal (carcinomatosis, tuberculosis, pancreatitis, síndrome nefrótico)',c:''}},
  ref:['Runyon BA, Montano AA, Akriviadis EA, et al. The serum-ascites albumin gradient is superior to the exudate-transudate concept in the differential diagnosis of ascites. Ann Intern Med. 1992;117(3):215-220.']});

/* NEFROLOGÍA Y ELECTROLITOS */
const kdigo=g=>g>=90?['G1: normal o alta','ok']:g>=60?['G2: levemente disminuida','ok']:g>=45?['G3a: leve a moderadamente disminuida','warn']:g>=30?['G3b: moderada a gravemente disminuida','warn']:g>=15?['G4: gravemente disminuida','bad']:['G5: falla renal','bad'];
add({id:'ckdepi',c:'Nefrología y electrolitos',t:'Filtración glomerular estimada (CKD-EPI 2021)',s:'Colaboración Epidemiológica de la Enfermedad Renal Crónica, sin raza',f:[n('cr','Creatinina sérica','miligramos por decilitro'),EDAD,SEXO],
  r:v=>{if(v.edad<18)return{n:'No aplica',u:'',i:'Ecuación validada en mayores de 18 años. En niños usa Schwartz.',c:'warn'};const f=v.sexo==='M',k=f?.7:.9,a=f?-.241:-.302,g=142*Math.pow(Math.min(v.cr/k,1),a)*Math.pow(Math.max(v.cr/k,1),-1.2)*Math.pow(.9938,v.edad)*(f?1.012:1);const q=kdigo(g);
    return{n:r0(g),u:'mililitros por minuto por 1.73 metros cuadrados',i:'Categoría '+q[0]+' según KDIGO 2024',c:q[1]}},
  ref:['Inker LA, Eneanya ND, Coresh J, et al. New creatinine- and cystatin C-based equations to estimate GFR without race. N Engl J Med. 2021;385(19):1737-1749.','Kidney Disease: Improving Global Outcomes (KDIGO) CKD Work Group. KDIGO 2024 Clinical Practice Guideline for the Evaluation and Management of Chronic Kidney Disease. Kidney Int. 2024;105(4S):S117-S314.']});
add({id:'cockcroft',c:'Nefrología y electrolitos',t:'Depuración de creatinina (Cockcroft-Gault)',s:'La que usan muchas fichas para ajustar dosis',f:[EDAD,PESO,n('cr','Creatinina sérica','miligramos por decilitro'),SEXO],
  r:v=>{const x=(140-v.edad)*v.peso/(72*v.cr)*(v.sexo==='M'?.85:1);return{n:r0(x),u:'mililitros por minuto',i:x<30?'Menor de 30: ajuste de dosis de muchos fármacos':x<60?'30 a 59: revisa ajustes de dosis':'60 o más',c:x<30?'bad':x<60?'warn':'ok',d:'Usa el peso real; en obesidad considera el peso ajustado.'}},
  ref:['Cockcroft DW, Gault MH. Prediction of creatinine clearance from serum creatinine. Nephron. 1976;16(1):31-41.']});
add({id:'schwartz',c:'Nefrología y electrolitos',t:'Filtración glomerular en niños (Schwartz a pie de cama)',s:'De 1 a 18 años',f:[TALLA,n('cr','Creatinina sérica','miligramos por decilitro')],
  r:v=>{const x=0.413*v.talla/v.cr;const q=kdigo(x);return{n:r0(x),u:'mililitros por minuto por 1.73 metros cuadrados',i:q[0],c:q[1]}},
  ref:['Schwartz GJ, Muñoz A, Schneider MF, et al. New equations to estimate GFR in children with CKD. J Am Soc Nephrol. 2009;20(3):629-637.']});
add({id:'albuminuria',c:'Nefrología y electrolitos',t:'Categoría de albuminuria',s:'Cociente albúmina-creatinina en orina',f:[n('acr','Cociente albúmina-creatinina','miligramos por gramo')],
  r:v=>{const x=v.acr;return{n:x<30?'A1':x<=300?'A2':'A3',u:'',i:x<30?'Normal o levemente aumentada (menor de 30)':x<=300?'Moderadamente aumentada (30 a 300)':'Gravemente aumentada (mayor de 300)',c:x<30?'ok':x<=300?'warn':'bad',d:'Confirma con 2 de 3 muestras en 3 a 6 meses.'}},
  ref:['KDIGO 2024 Clinical Practice Guideline for the Evaluation and Management of Chronic Kidney Disease. Kidney Int. 2024;105(4S):S117-S314.']});
add({id:'ag',c:'Nefrología y electrolitos',t:'Brecha aniónica',s:'Con corrección por albúmina',f:[n('na','Sodio','miliequivalentes por litro'),n('cl','Cloro','miliequivalentes por litro'),n('hco3','Bicarbonato','miliequivalentes por litro'),n('alb','Albúmina','gramos por decilitro',{opt:1})],
  r:v=>{const x=v.na-(v.cl+v.hco3),cor=v.alb?x+2.5*(4-v.alb):null,ref=cor??x;return{n:r1(x),u:'miliequivalentes por litro',i:ref>12?'Elevada (mayor de 12): acidosis por cetoácidos, lactato, tóxicos o uremia':ref<6?'Baja: hipoalbuminemia, paraproteínas o error de laboratorio':'Normal (alrededor de 8 a 12; depende del laboratorio)',c:ref>12?'warn':'ok',d:cor!==null?`Corregida por albúmina: ${r1(cor)}`:''}},
  ref:['Kraut JA, Madias NE. Serum anion gap: its uses and limitations in clinical medicine. Clin J Am Soc Nephrol. 2007;2(1):162-174.','Figge J, Jabor A, Kazda A, Fencl V. Anion gap and hypoalbuminemia. Crit Care Med. 1998;26(11):1807-1810.']});
add({id:'nacorr',c:'Nefrología y electrolitos',t:'Sodio corregido por glucosa',s:'Hiperglucemia',f:[n('na','Sodio medido','miliequivalentes por litro'),n('glu','Glucosa','miligramos por decilitro')],
  r:v=>{const k=(v.glu-100)/100;return{n:r1(v.na+1.6*k),u:'miliequivalentes por litro (factor 1.6, Katz)',i:`Con el factor 2.4 de Hillier: ${r1(v.na+2.4*k)}`,c:''}},
  ref:['Katz MA. Hyperglycemia-induced hyponatremia: calculation of expected serum sodium depression. N Engl J Med. 1973;289(16):843-844.','Hillier TA, Abbott RD, Barrett EJ. Hyponatremia: evaluating the correction factor for hyperglycemia. Am J Med. 1999;106(4):399-403.']});
add({id:'cacorr',c:'Nefrología y electrolitos',t:'Calcio corregido por albúmina',s:'',f:[n('ca','Calcio total','miligramos por decilitro'),n('alb','Albúmina','gramos por decilitro')],
  r:v=>{const x=v.ca+0.8*(4-v.alb);return{n:r1(x),u:'miligramos por decilitro',i:x>10.5?'Hipercalcemia':x<8.5?'Hipocalcemia':'Dentro de lo habitual (8.5 a 10.5)',c:x>10.5||x<8.5?'warn':'ok',d:'Si hay duda, mide calcio iónico.'}},
  ref:['Payne RB, Little AJ, Williams RB, Milner JR. Interpretation of serum calcium in patients with abnormal serum proteins. Br Med J. 1973;4(5893):643-646.']});
add({id:'osm',c:'Nefrología y electrolitos',t:'Osmolalidad sérica calculada y brecha osmolar',s:'',f:[n('na','Sodio','miliequivalentes por litro'),n('glu','Glucosa','miligramos por decilitro'),n('bun','Nitrógeno ureico','miligramos por decilitro'),n('med','Osmolalidad medida','miliosmoles por kilogramo',{opt:1})],
  r:v=>{const x=2*v.na+v.glu/18+v.bun/2.8;const g=v.med?v.med-x:null;return{n:r0(x),u:'miliosmoles por kilogramo',i:x>295?'Hiperosmolar':x<275?'Hipoosmolar':'Normal (275 a 295)',c:x>320?'bad':(x>295||x<275)?'warn':'ok',d:g!==null?`Brecha osmolar: ${r0(g)}${g>10?' (mayor de 10: considerar alcoholes tóxicos)':''}`:''}},
  ref:['Rasouli M. Basic concepts and practical equations on osmolality: Biochemical approach. Clin Biochem. 2016;49(12):936-941.']});
add({id:'aguaLibre',c:'Nefrología y electrolitos',t:'Déficit de agua libre',s:'Hipernatremia',f:[PESO,n('na','Sodio actual','miliequivalentes por litro'),s('grupo','Paciente',[['Hombre adulto',0.6],['Mujer adulta',0.5],['Hombre adulto mayor',0.5],['Mujer adulta mayor',0.45],['Niño',0.6]])],
  r:v=>{const act=v.peso*v.grupo,x=act*(v.na/140-1);return{n:r1(x)+' litros',u:`Agua corporal total ${r1(act)} litros`,i:'Corrige sin bajar el sodio más de 10 a 12 miliequivalentes por litro en 24 horas.',c:'',d:'Suma las pérdidas continuas.'}},
  ref:['Adrogué HJ, Madias NE. Hypernatremia. N Engl J Med. 2000;342(20):1493-1499.']});
add({id:'adrogue',c:'Nefrología y electrolitos',t:'Fórmula de Adrogué-Madias',s:'Cambio de sodio por litro de solución',f:[PESO,n('na','Sodio actual','miliequivalentes por litro'),s('grupo','Paciente',[['Hombre adulto',0.6],['Mujer adulta',0.5],['Hombre adulto mayor',0.5],['Mujer adulta mayor',0.45],['Niño',0.6]]),s('sol','Solución',[['Cloruro de sodio al 3%',513],['Cloruro de sodio al 0.9%',154],['Hartmann (Ringer lactato)',130],['Cloruro de sodio al 0.45%',77],['Glucosa al 5%',0]])],
  r:v=>{const act=v.peso*v.grupo,x=(v.sol-v.na)/(act+1);return{n:(x>0?'+':'')+r1(x),u:'miliequivalentes por litro por cada litro infundido',i:'En hiponatremia crónica no corrijas más de 8 a 10 miliequivalentes por litro en 24 horas: riesgo de desmielinización osmótica.',c:''}},
  ref:['Adrogué HJ, Madias NE. Hyponatremia. N Engl J Med. 2000;342(21):1581-1589.']});
add({id:'fena',c:'Nefrología y electrolitos',t:'Fracción excretada de sodio y de urea',s:'Lesión renal aguda: prerrenal o renal',f:[n('una','Sodio urinario','miliequivalentes por litro'),n('pna','Sodio sérico','miliequivalentes por litro'),n('ucr','Creatinina urinaria','miligramos por decilitro'),n('pcr','Creatinina sérica','miligramos por decilitro'),n('uu','Urea urinaria (opcional)','miligramos por decilitro',{opt:1}),n('pu','Urea sérica (opcional)','miligramos por decilitro',{opt:1})],
  r:v=>{const x=(v.una*v.pcr)/(v.pna*v.ucr)*100,fu=(v.uu&&v.pu)?(v.uu*v.pcr)/(v.pu*v.ucr)*100:null;return{n:r2(x)+'%',u:'fracción excretada de sodio',i:x<1?'Menor de 1%: sugiere causa prerrenal':x>2?'Mayor de 2%: sugiere necrosis tubular aguda':'1 a 2%: indeterminado',c:'',d:fu!==null?`Fracción excretada de urea ${r1(fu)}% (menor de 35%: prerrenal; útil si recibió diuréticos)`:'Con diuréticos, usa la fracción excretada de urea.'}},
  ref:['Espinel CH. The FENa test. Use in the differential diagnosis of acute renal failure. JAMA. 1976;236(6):579-581.','Carvounis CP, Nisar S, Guro-Razuman S. Significance of the fractional excretion of urea in the differential diagnosis of acute renal failure. Kidney Int. 2002;62(6):2223-2229.']});

/* ENDOCRINOLOGÍA */
add({id:'findrisc',c:'Endocrinología',t:'Escala FINDRISC',s:'Riesgo de diabetes tipo 2 a 10 años',f:[
  s('e','Edad',[['Menor de 45 años',0],['45 a 54 años',2],['55 a 64 años',3],['Mayor de 64 años',4]]),
  s('imc','Índice de masa corporal',[['Menor de 25',0],['25 a 30',1],['Mayor de 30',3]]),
  s('cin','Circunferencia de cintura',[['Hombre menor de 94 o mujer menor de 80 centímetros',0],['Hombre 94 a 102 o mujer 80 a 88',3],['Hombre mayor de 102 o mujer mayor de 88',4]]),
  s('act','Actividad física de 30 minutos al día',[['Sí',0],['No',2]]),s('fru','Come verduras o frutas todos los días',[['Sí',0],['No',1]]),
  s('hta','Ha tomado medicamentos para la presión',[['No',0],['Sí',2]]),s('glu','Le han encontrado glucosa alta alguna vez',[['No',0],['Sí',5]]),
  s('fam','Familiares con diabetes',[['Ninguno',0],['Abuelos, tíos o primos',3],['Padres, hermanos o hijos',5]])],
  r:v=>{const x=['e','imc','cin','act','fru','hta','glu','fam'].reduce((a,k)=>a+v[k],0);const q=rng(x,[[6,'Menor de 7: riesgo bajo (1 de cada 100)','ok'],[11,'7 a 11: ligeramente elevado (1 de cada 25)','ok'],[14,'12 a 14: moderado (1 de cada 6)','warn'],[20,'15 a 20: alto (1 de cada 3)','bad'],[26,'Mayor de 20: muy alto (1 de cada 2)','bad']]);return{n:x,u:'puntos',i:q[1],c:q[2]}},
  ref:['Lindström J, Tuomilehto J. The diabetes risk score: a practical tool to predict type 2 diabetes risk. Diabetes Care. 2003;26(3):725-731.']});
add({id:'dmcrit',c:'Endocrinología',t:'Criterios diagnósticos de diabetes y prediabetes',s:'Asociación Americana de Diabetes',f:[n('ga','Glucosa en ayuno','miligramos por decilitro',{opt:1}),n('a1c','Hemoglobina glucosilada','por ciento',{opt:1}),n('g2h','Glucosa a 2 horas de la carga de 75 gramos','miligramos por decilitro',{opt:1}),n('gal','Glucosa al azar','miligramos por decilitro',{opt:1}),c('sint','Síntomas clásicos de hiperglucemia o crisis hiperglucémica')],
  r:v=>{const dm=[],pre=[];if(v.ga!=null){v.ga>=126?dm.push('ayuno'):v.ga>=100&&pre.push('glucosa alterada en ayuno')}if(v.a1c!=null){v.a1c>=6.5?dm.push('hemoglobina glucosilada'):v.a1c>=5.7&&pre.push('hemoglobina glucosilada')}if(v.g2h!=null){v.g2h>=200?dm.push('curva de tolerancia'):v.g2h>=140&&pre.push('intolerancia a la glucosa')}
    const azar=v.gal!=null&&v.gal>=200&&v.sint;if(v.ga==null&&v.a1c==null&&v.g2h==null&&v.gal==null)return null;
    if(azar)return{n:'Diabetes',u:'',i:'Glucosa al azar de 200 o más con síntomas: diagnóstico sin necesidad de confirmar.',c:'bad'};
    if(dm.length)return{n:dm.length>=2?'Diabetes':'Compatible con diabetes',u:'',i:dm.length>=2?'Dos criterios en la misma muestra o en muestras distintas confirman el diagnóstico.':`Criterio por ${dm[0]}: confírmalo con una segunda prueba.`,c:'bad'};
    if(pre.length)return{n:'Prediabetes',u:'',i:'Por '+pre.join(', ')+'.',c:'warn'};return{n:'Sin criterios',u:'',i:'Valores dentro de lo normal.',c:'ok'}},
  ref:['American Diabetes Association Professional Practice Committee. 2. Diagnosis and Classification of Diabetes: Standards of Care in Diabetes—2025. Diabetes Care. 2025;48(Suppl 1):S27-S49.']});
add({id:'homa',c:'Endocrinología',t:'Índice HOMA-IR',s:'Resistencia a la insulina',f:[n('glu','Glucosa en ayuno','miligramos por decilitro'),n('ins','Insulina en ayuno','microunidades por mililitro')],
  r:v=>({n:r2(v.glu*v.ins/405),u:'',i:'El punto de corte depende de la población y del laboratorio; en adultos mexicanos se han propuesto valores alrededor de 2.5 a 3.',c:''}),
  ref:['Matthews DR, Hosker JP, Rudenski AS, et al. Homeostasis model assessment: insulin resistance and beta-cell function from fasting plasma glucose and insulin concentrations in man. Diabetologia. 1985;28(7):412-419.']});
add({id:'eag',c:'Endocrinología',t:'Glucosa promedio estimada',s:'A partir de la hemoglobina glucosilada',f:[n('a1c','Hemoglobina glucosilada','por ciento')],
  r:v=>{const x=28.7*v.a1c-46.7;return{n:r0(x),u:'miligramos por decilitro',i:`${r1(x/18)} milimoles por litro`,c:''}},
  ref:['Nathan DM, Kuenen J, Borg R, et al. Translating the A1C assay into estimated average glucose values. Diabetes Care. 2008;31(8):1473-1478.']});

/* NEUROLOGÍA */
add(esc('nihss','Neurología','Escala de los Institutos Nacionales de Salud para el evento vascular cerebral','Gravedad del déficit neurológico',[
  s('1a','1a. Nivel de conciencia',[['Alerta',0],['Somnoliento, responde a estímulo menor',1],['Requiere estímulos repetidos o dolorosos',2],['Solo respuestas reflejas o sin respuesta',3]]),
  s('1b','1b. Preguntas (mes y edad)',[['Ambas correctas',0],['Una correcta',1],['Ninguna correcta',2]]),
  s('1c','1c. Órdenes (abrir y cerrar ojos, apretar la mano)',[['Ambas correctas',0],['Una correcta',1],['Ninguna',2]]),
  s('2','2. Mirada',[['Normal',0],['Parálisis parcial',1],['Desviación forzada',2]]),
  s('3','3. Campos visuales',[['Normales',0],['Hemianopsia parcial',1],['Hemianopsia completa',2],['Hemianopsia bilateral o ceguera',3]]),
  s('4','4. Parálisis facial',[['Normal',0],['Menor',1],['Parcial',2],['Completa',3]]),
  s('5a','5a. Motor del brazo izquierdo',[['Sin caída',0],['Cae antes de 10 segundos',1],['Algún esfuerzo contra la gravedad',2],['Sin esfuerzo contra la gravedad',3],['Sin movimiento',4]]),
  s('5b','5b. Motor del brazo derecho',[['Sin caída',0],['Cae antes de 10 segundos',1],['Algún esfuerzo contra la gravedad',2],['Sin esfuerzo contra la gravedad',3],['Sin movimiento',4]]),
  s('6a','6a. Motor de la pierna izquierda',[['Sin caída',0],['Cae antes de 5 segundos',1],['Algún esfuerzo contra la gravedad',2],['Sin esfuerzo contra la gravedad',3],['Sin movimiento',4]]),
  s('6b','6b. Motor de la pierna derecha',[['Sin caída',0],['Cae antes de 5 segundos',1],['Algún esfuerzo contra la gravedad',2],['Sin esfuerzo contra la gravedad',3],['Sin movimiento',4]]),
  s('7','7. Ataxia de extremidades',[['Ausente',0],['En una extremidad',1],['En dos extremidades',2]]),
  s('8','8. Sensibilidad',[['Normal',0],['Pérdida leve a moderada',1],['Pérdida grave o total',2]]),
  s('9','9. Lenguaje',[['Normal',0],['Afasia leve a moderada',1],['Afasia grave',2],['Mutismo o afasia global',3]]),
  s('10','10. Disartria',[['Normal',0],['Leve a moderada',1],['Grave o anartria',2]]),
  s('11','11. Extinción e inatención',[['Sin alteración',0],['En una modalidad',1],['En más de una modalidad o hemiinatención profunda',2]])],
  [[0,'0: sin déficit medible','ok'],[4,'1 a 4: evento vascular menor','ok'],[15,'5 a 15: moderado','warn'],[20,'16 a 20: moderado a grave','bad'],[42,'21 a 42: grave','bad']],
  ['Brott T, Adams HP Jr, Olinger CP, et al. Measurements of acute cerebral infarction: a clinical examination scale. Stroke. 1989;20(7):864-870.']));
add(esc('abcd2','Neurología','Escala ABCD2','Riesgo de evento vascular tras isquemia cerebral transitoria',[
  c('a','Edad de 60 años o más'),c('b','Presión arterial de 140/90 o más en la valoración inicial'),s('cl','Cuadro clínico',[['Otros síntomas',0],['Alteración del lenguaje sin debilidad',1],['Debilidad unilateral',2]]),s('d','Duración',[['Menos de 10 minutos',0],['10 a 59 minutos',1],['60 minutos o más',2]]),c('dm','Diabetes')],
  [[3,'0 a 3: riesgo bajo (1% a 2 días)','ok'],[5,'4 a 5: riesgo moderado (4.1% a 2 días)','warn'],[7,'6 a 7: riesgo alto (8.1% a 2 días)','bad']],
  ['Johnston SC, Rothwell PM, Nguyen-Huynh MN, et al. Validation and refinement of scores to predict very early stroke risk after transient ischaemic attack. Lancet. 2007;369(9558):283-292.']));
add({id:'rankin',c:'Neurología',t:'Escala de Rankin modificada',s:'Discapacidad funcional',f:[s('r','Situación del paciente',[['Sin síntomas',0],['Síntomas sin discapacidad significativa',1],['Discapacidad leve: no realiza todas sus actividades previas, pero se vale por sí mismo',2],['Discapacidad moderada: requiere algo de ayuda, camina sin ayuda',3],['Discapacidad moderada a grave: no camina ni atiende sus necesidades sin ayuda',4],['Discapacidad grave: encamado, incontinente, cuidados constantes',5],['Muerte',6]])],
  r:v=>({n:v.r,u:'',i:v.r<=2?'Independencia funcional':'Dependencia',c:v.r<=1?'ok':v.r<=3?'warn':'bad'}),
  ref:['van Swieten JC, Koudstaal PJ, Visser MC, et al. Interobserver agreement for the assessment of handicap in stroke patients. Stroke. 1988;19(5):604-607.']});
add({id:'hunthess',c:'Neurología',t:'Escala de Hunt y Hess',s:'Hemorragia subaracnoidea',f:[s('g','Cuadro clínico',[['Asintomático o cefalea leve y rigidez de nuca leve',1],['Cefalea moderada a grave, rigidez de nuca, sin déficit salvo de pares craneales',2],['Somnolencia, confusión o déficit focal leve',3],['Estupor, hemiparesia moderada a grave',4],['Coma profundo, rigidez de descerebración',5]])],
  r:v=>({n:'Grado '+['I','II','III','IV','V'][v.g-1],u:'',i:'A mayor grado, mayor mortalidad quirúrgica.',c:v.g>=4?'bad':v.g===3?'warn':'ok'}),
  ref:['Hunt WE, Hess RM. Surgical risk as related to time of intervention in the repair of intracranial aneurysms. J Neurosurg. 1968;28(1):14-20.']});
add({id:'minicog',c:'Neurología',t:'Mini-Cog',s:'Detección rápida de deterioro cognitivo',f:[s('p','Palabras recordadas de las 3',[['Ninguna',0],['Una',1],['Dos',2],['Tres',3]]),s('r','Dibujo del reloj',[['Anormal',0],['Normal: todos los números y las manecillas en la hora pedida',2]])],
  r:v=>{const x=v.p+v.r;return{n:x+'/5',u:'',i:x<3?'Menos de 3: tamizaje positivo; requiere evaluación cognitiva completa':'3 o más: tamizaje negativo',c:x<3?'warn':'ok'}},
  ref:['Borson S, Scanlan J, Brush M, et al. The Mini-Cog: a cognitive vital signs measure for dementia screening in multi-lingual elderly. Int J Geriatr Psychiatry. 2000;15(11):1021-1027.']});

/* SALUD MENTAL */
const FRQ=[['Ningún día',0],['Varios días',1],['Más de la mitad de los días',2],['Casi todos los días',3]];
add({id:'phq9',c:'Salud mental',t:'Cuestionario de salud del paciente de 9 preguntas',s:'Depresión en las últimas 2 semanas',f:[
  t('Durante las últimas 2 semanas, ¿qué tan seguido le han molestado los siguientes problemas?'),
  s('1','Poco interés o placer en hacer las cosas',FRQ),s('2','Se ha sentido decaído, deprimido o sin esperanza',FRQ),s('3','Dificultad para dormir o permanecer dormido, o ha dormido demasiado',FRQ),s('4','Se ha sentido cansado o con poca energía',FRQ),s('5','Sin apetito o ha comido en exceso',FRQ),s('6','Se ha sentido mal consigo mismo, que es un fracaso o que ha quedado mal con usted o con su familia',FRQ),s('7','Dificultad para concentrarse, por ejemplo al leer o ver la televisión',FRQ),s('8','Se ha movido o hablado tan lento que otros lo notaron, o lo contrario: muy inquieto',FRQ),s('9','Pensamientos de que estaría mejor muerto o de lastimarse de alguna forma',FRQ)],
  r:v=>{const x=['1','2','3','4','5','6','7','8','9'].reduce((a,k)=>a+v[k],0);const q=rng(x,[[4,'0 a 4: mínima','ok'],[9,'5 a 9: leve','ok'],[14,'10 a 14: moderada','warn'],[19,'15 a 19: moderadamente grave','bad'],[27,'20 a 27: grave','bad']]);
    return{n:x,u:'puntos',i:q[1],c:q[2],d:v['9']>0?'La pregunta 9 es positiva: evalúa el riesgo de suicidio en esta misma consulta.':''}},
  ref:['Kroenke K, Spitzer RL, Williams JB. The PHQ-9: validity of a brief depression severity measure. J Gen Intern Med. 2001;16(9):606-613.']});
add({id:'gad7',c:'Salud mental',t:'Escala de trastorno de ansiedad generalizada de 7 preguntas',s:'Ansiedad en las últimas 2 semanas',f:[
  t('Durante las últimas 2 semanas, ¿qué tan seguido ha tenido molestias por los siguientes problemas?'),
  s('1','Se ha sentido nervioso, ansioso o con los nervios de punta',FRQ),s('2','No ha podido dejar de preocuparse o controlar su preocupación',FRQ),s('3','Se ha preocupado demasiado por diferentes cosas',FRQ),s('4','Ha tenido dificultad para relajarse',FRQ),s('5','Se ha sentido tan inquieto que no ha podido quedarse quieto',FRQ),s('6','Se ha molestado o irritado fácilmente',FRQ),s('7','Ha sentido miedo de que algo terrible fuera a pasar',FRQ)],
  r:v=>{const x=['1','2','3','4','5','6','7'].reduce((a,k)=>a+v[k],0);const q=rng(x,[[4,'0 a 4: mínima','ok'],[9,'5 a 9: leve','ok'],[14,'10 a 14: moderada; 10 o más amerita evaluación','warn'],[21,'15 a 21: grave','bad']]);return{n:x,u:'puntos',i:q[1],c:q[2]}},
  ref:['Spitzer RL, Kroenke K, Williams JB, Löwe B. A brief measure for assessing generalized anxiety disorder: the GAD-7. Arch Intern Med. 2006;166(10):1092-1097.']});
add({id:'auditc',c:'Salud mental',t:'Prueba AUDIT-C',s:'Consumo de riesgo de alcohol, 3 preguntas',f:[SEXO,
  s('1','¿Con qué frecuencia toma alguna bebida alcohólica?',[['Nunca',0],['Una vez al mes o menos',1],['2 a 4 veces al mes',2],['2 a 3 veces por semana',3],['4 o más veces por semana',4]]),
  s('2','¿Cuántas bebidas toma en un día típico en que bebe?',[['1 a 2',0],['3 a 4',1],['5 a 6',2],['7 a 9',3],['10 o más',4]]),
  s('3','¿Con qué frecuencia toma 6 o más bebidas en una ocasión?',[['Nunca',0],['Menos de una vez al mes',1],['Mensualmente',2],['Semanalmente',3],['Diario o casi diario',4]])],
  r:v=>{const x=v['1']+v['2']+v['3'],lim=v.sexo==='M'?3:4;return{n:x,u:'puntos',i:x>=lim?`Positivo (${lim} o más en ${v.sexo==='M'?'mujeres':'hombres'}): consumo de riesgo; aplica intervención breve`:'Negativo',c:x>=lim?'warn':'ok'}},
  ref:['Bush K, Kivlahan DR, McDonell MB, et al. The AUDIT alcohol consumption questions (AUDIT-C). Arch Intern Med. 1998;158(16):1789-1795.']});
add(esc('fagerstrom','Salud mental','Prueba de Fagerström','Dependencia a la nicotina',[
  s('1','¿Cuánto tiempo después de despertar fuma su primer cigarro?',[['5 minutos o menos',3],['6 a 30 minutos',2],['31 a 60 minutos',1],['Más de 60 minutos',0]]),
  s('2','¿Le cuesta no fumar en lugares donde está prohibido?',SI),s('3','¿Qué cigarro le costaría más dejar?',[['El primero de la mañana',1],['Cualquier otro',0]]),
  s('4','¿Cuántos cigarros fuma al día?',[['10 o menos',0],['11 a 20',1],['21 a 30',2],['31 o más',3]]),s('5','¿Fuma más en las primeras horas después de despertar?',SI),s('6','¿Fuma aunque esté enfermo en cama?',SI)],
  [[2,'0 a 2: dependencia muy baja','ok'],[4,'3 a 4: baja','ok'],[5,'5: media','warn'],[7,'6 a 7: alta','bad'],[10,'8 a 10: muy alta','bad']],
  ['Heatherton TF, Kozlowski LT, Frecker RC, Fagerström KO. The Fagerström Test for Nicotine Dependence. Br J Addict. 1991;86(9):1119-1127.']));

