const fd=d=>d.toLocaleDateString('es-MX',{day:'numeric',month:'long',year:'numeric'});
const pd=x=>{if(!x)return null;const a=String(x).split('-').map(Number);return a.length===3?new Date(a[0],a[1]-1,a[2]):null};
add({id:'sdg',c:'Ginecología y obstetricia',t:'Semanas de gestación y fecha probable de parto',s:'Por fecha de última menstruación',f:[n('fum','Fecha de última menstruación','',{tipo:'date',pk:'fum'}),n('ref','Fecha de cálculo (opcional, hoy por omisión)','',{tipo:'date',opt:1})],
  r:v=>{const f=pd(v.fum);if(!f)return null;const r=pd(v.ref)||new Date();r.setHours(0,0,0,0);const d=Math.round((r-f)/864e5);if(d<0||d>320)return{n:'Fecha fuera de rango',u:'',i:'Revisa la fecha.',c:'warn'};const x=new Date(f);x.setDate(x.getDate()+280);const w=Math.floor(d/7);
    return{n:`${w} semanas y ${d%7} días`,u:w<14?'Primer trimestre':w<28?'Segundo trimestre':'Tercer trimestre',i:'Fecha probable de parto: '+fd(x),c:''}},
  ref:['Naegele FC. Lehrbuch der Geburtshülfe. Heidelberg; 1836.','American College of Obstetricians and Gynecologists. Committee Opinion No. 700: Methods for Estimating the Due Date. Obstet Gynecol. 2017;129(5):e150-e154.']});
add({id:'fppus',c:'Ginecología y obstetricia',t:'Edad gestacional por ultrasonido',s:'',f:[n('fus','Fecha del ultrasonido','',{tipo:'date'}),n('w','Semanas por ultrasonido',''),n('d','Días adicionales','',{opt:1})],
  r:v=>{const f=pd(v.fus);if(!f)return null;const hoy=new Date();hoy.setHours(0,0,0,0);const t=Math.round(v.w*7+(v.d||0)+(hoy-f)/864e5);const fpp=new Date(f);fpp.setDate(fpp.getDate()+280-Math.round(v.w*7+(v.d||0)));
    return{n:`${Math.floor(t/7)} semanas y ${t%7} días hoy`,u:'',i:'Fecha probable de parto: '+fd(fpp),c:'',d:'El ultrasonido del primer trimestre es el más preciso para fechar el embarazo.'}},
  ref:['American College of Obstetricians and Gynecologists. Committee Opinion No. 700: Methods for Estimating the Due Date. Obstet Gynecol. 2017;129(5):e150-e154.']});
