add({id:'ganancia',c:'Ginecología y obstetricia',t:'Ganancia de peso recomendada en el embarazo',s:'Instituto de Medicina, 2009',f:[n('pp','Peso antes del embarazo','kilogramos'),TALLA,n('pa','Peso actual (opcional)','kilogramos',{opt:1}),c('mult','Embarazo gemelar',0)],
  r:v=>{const m=v.talla/100,i=v.pp/(m*m);const R=v.mult?(i<18.5?null:i<25?[17,25]:i<30?[14,23]:[11,19]):(i<18.5?[12.5,18]:i<25?[11.5,16]:i<30?[7,11.5]:[5,9]);const lab=i<18.5?'bajo peso':i<25?'peso normal':i<30?'sobrepeso':'obesidad';
    const g=v.pa?v.pa-v.pp:null;return{n:R?`${R[0]} a ${R[1]} kilogramos`:'Sin recomendación',u:`Índice de masa corporal pregestacional ${r1(i)} (${lab})`,i:R?'Ganancia total recomendada al término del embarazo.':'No hay recomendación para gemelar con bajo peso.',c:'',d:g!==null?`Ganancia actual: ${r1(g)} kilogramos.`:''}},
  ref:['Institute of Medicine (US) and National Research Council. Weight Gain During Pregnancy: Reexamining the Guidelines. Washington, DC: National Academies Press; 2009.']});
add({id:'preecl',c:'Ginecología y obstetricia',t:'Factores de riesgo de preeclampsia',s:'Indicación de ácido acetilsalicílico a dosis baja',f:[h('Riesgo alto'),c('a1','Preeclampsia en un embarazo previo',0),c('a2','Embarazo múltiple',0),c('a3','Hipertensión crónica',0),c('a4','Diabetes tipo 1 o 2',0),c('a5','Enfermedad renal',0),c('a6','Enfermedad autoinmune (lupus o síndrome antifosfolípidos)',0),h('Riesgo moderado'),c('m1','Nuliparidad',0),c('m2','Obesidad (índice de masa corporal mayor de 30)',0),c('m3','Madre o hermana con preeclampsia',0),c('m4','Edad de 35 años o más',0),c('m5','Antecedente de recién nacido con bajo peso o intervalo entre embarazos mayor de 10 años',0),c('m6','Condiciones sociodemográficas de riesgo',0)],
  r:v=>{const a=['a1','a2','a3','a4','a5','a6'].filter(k=>v[k]).length,m=['m1','m2','m3','m4','m5','m6'].filter(k=>v[k]).length;const ind=a>=1||m>=2;return{n:ind?'Indicado':'No indicado',u:`${a} de riesgo alto, ${m} de riesgo moderado`,i:ind?'Se recomienda ácido acetilsalicílico a dosis baja desde las 12 semanas (idealmente antes de las 16) hasta el parto.':'Con un solo factor moderado se puede considerar según el contexto.',c:ind?'warn':'ok'}},
  ref:['US Preventive Services Task Force. Aspirin Use to Prevent Preeclampsia and Related Morbidity and Mortality: Recommendation Statement. JAMA. 2021;326(12):1186-1191.','American College of Obstetricians and Gynecologists. Committee Opinion No. 743: Low-Dose Aspirin Use During Pregnancy. Obstet Gynecol. 2018;132(1):e44-e52.']});

