add({id:'cam',c:'Geriatría',t:'Método de Evaluación de la Confusión',s:'Delirium',f:[c('1','1. Inicio agudo y curso fluctuante'),c('2','2. Inatención'),c('3','3. Pensamiento desorganizado'),c('4','4. Alteración del nivel de conciencia')],
  r:v=>{const x=v['1']&&v['2']&&(v['3']||v['4']);return{n:x?'Positivo':'Negativo',u:'',i:x?'Cumple criterios de delirium: busca la causa (infección, fármacos, metabólica, retención urinaria, dolor).':'Requiere 1 y 2, más 3 o 4.',c:x?'bad':'ok'}},
  ref:['Inouye SK, van Dyck CH, Alessi CA, et al. Clarifying confusion: the confusion assessment method. Ann Intern Med. 1990;113(12):941-948.']});

