add({id:'asa',c:'Valoración preoperatoria',t:'Clasificación del estado físico de la Sociedad Americana de Anestesiólogos',s:'',f:[s('a','Estado del paciente',[['Sano',1],['Enfermedad sistémica leve',2],['Enfermedad sistémica grave',3],['Enfermedad sistémica grave que amenaza la vida de forma constante',4],['Moribundo, no se espera que sobreviva sin la cirugía',5],['Muerte cerebral, donante de órganos',6]]),c('u','Cirugía de urgencia (agrega la letra E)',0)],
  r:v=>({n:'ASA '+['I','II','III','IV','V','VI'][v.a-1]+(v.u?' E':''),u:'',i:['Sin enfermedad orgánica, fisiológica ni psiquiátrica','Por ejemplo, fumador, obesidad leve, diabetes o hipertensión bien controladas','Por ejemplo, diabetes o hipertensión mal controladas, obesidad mórbida, enfermedad pulmonar obstructiva crónica','Por ejemplo, infarto reciente, sepsis, insuficiencia cardiaca grave','Por ejemplo, aneurisma roto, traumatismo masivo','Para procuración de órganos'][v.a-1],c:v.a>=4?'bad':v.a===3?'warn':'ok'}),
  ref:['American Society of Anesthesiologists. ASA Physical Status Classification System. Actualización aprobada el 13 de diciembre de 2020.']});
add(esc('lee','Valoración preoperatoria','Índice de riesgo cardiaco revisado de Lee','Complicaciones cardiacas en cirugía no cardiaca',[c('cx','Cirugía de alto riesgo (intraperitoneal, intratorácica o vascular suprainguinal)'),c('ci','Cardiopatía isquémica'),c('ic','Insuficiencia cardiaca'),c('ev','Enfermedad cerebrovascular'),c('dm','Diabetes con insulina'),c('cr','Creatinina mayor de 2 miligramos por decilitro')],
  [[0,'Clase I: riesgo 0.4%','ok'],[1,'Clase II: riesgo 0.9%','ok'],[2,'Clase III: riesgo 6.6%','warn'],[6,'Clase IV (3 o más): riesgo 11%','bad']],
  ['Lee TH, Marcantonio ER, Mangione CM, et al. Derivation and prospective validation of a simple index for prediction of cardiac risk of major noncardiac surgery. Circulation. 1999;100(10):1043-1049.']));
add(esc('apfel','Valoración preoperatoria','Escala de Apfel','Náusea y vómito posoperatorios',[c('m','Sexo femenino'),c('n','No fumador'),c('h','Antecedente de náusea posoperatoria o cinetosis'),c('o','Uso de opioides en el posoperatorio')],
  [[0,'0: riesgo de 10%','ok'],[1,'1: 20%','ok'],[2,'2: 40%','warn'],[3,'3: 60%','bad'],[4,'4: 80%','bad']],
  ['Apfel CC, Läärä E, Koivuranta M, et al. A simplified risk score for predicting postoperative nausea and vomiting. Anesthesiology. 1999;91(3):693-700.']));
add({id:'psp',c:'Valoración preoperatoria',t:'Pérdida sanguínea permisible',s:'',f:[PESO,s('g','Paciente',[['Hombre adulto (70 mililitros por kilo)',70],['Mujer adulta (65 mililitros por kilo)',65],['Niño (75 a 80 mililitros por kilo)',78],['Lactante (80 mililitros por kilo)',80],['Recién nacido de término (85 mililitros por kilo)',85]]),n('hi','Hematocrito inicial','por ciento'),n('hm','Hematocrito mínimo aceptable','por ciento')],
  r:v=>{const vse=v.peso*v.g,x=vse*(v.hi-v.hm)/v.hi;return{n:r0(x)+' mililitros',u:`Volumen sanguíneo estimado ${r0(vse)} mililitros`,i:'Estimación aproximada; el umbral de transfusión depende del estado clínico.',c:''}},
  ref:['Gross JB. Estimating allowable blood loss: corrected for dilution. Anesthesiology. 1983;58(3):277-280.']});

/* NUTRICIÓN */
add({id:'imc',c:'Nutrición',t:'Índice de masa corporal',s:'Adultos',f:[PESO,TALLA],
  r:v=>{const m=v.talla/100,x=v.peso/(m*m);const q=x<18.5?['Bajo peso','warn']:x<25?['Peso normal','ok']:x<30?['Sobrepeso','warn']:x<35?['Obesidad grado I','bad']:x<40?['Obesidad grado II','bad']:['Obesidad grado III','bad'];return{n:r1(x),u:'kilogramos por metro cuadrado',i:q[0],c:q[1],d:'En niños y adolescentes se interpreta con percentiles para la edad.'}},
  ref:['World Health Organization. Obesity: preventing and managing the global epidemic. WHO Technical Report Series 894. Ginebra: OMS; 2000.']});
add({id:'pideal',c:'Nutrición',t:'Peso ideal y peso ajustado',s:'Fórmula de Devine',f:[TALLA,SEXO,n('peso','Peso real (opcional)','kilogramos',{opt:1,pk:'peso'})],
  r:v=>{const x=(v.sexo==='H'?50:45.5)+2.3*(v.talla/2.54-60);const aj=v.peso&&v.peso>x?x+0.4*(v.peso-x):null;return{n:r1(x)+' kilogramos',u:'peso ideal',i:aj?`Peso ajustado: ${r1(aj)} kilogramos (para dosificar en obesidad)`:'',c:'',d:v.peso?`El peso real es ${r0(v.peso/x*100)}% del ideal.`:''}},
  ref:['Devine BJ. Gentamicin therapy. Drug Intell Clin Pharm. 1974;8:650-655.']});
add({id:'mifflin',c:'Nutrición',t:'Gasto energético en reposo (Mifflin-St Jeor)',s:'',f:[PESO,TALLA,EDAD,SEXO,s('af','Actividad',[['Sedentario (1.2)',1.2],['Ligera (1.375)',1.375],['Moderada (1.55)',1.55],['Intensa (1.725)',1.725]])],
  r:v=>{const x=10*v.peso+6.25*v.talla-5*v.edad+(v.sexo==='H'?5:-161);return{n:r0(x)+' kilocalorías al día',u:'en reposo',i:`Con actividad: ${r0(x*v.af)} kilocalorías al día`,c:''}},
  ref:['Mifflin MD, St Jeor ST, Hill LA, et al. A new predictive equation for resting energy expenditure in healthy individuals. Am J Clin Nutr. 1990;51(2):241-247.']});
add({id:'cintura',c:'Nutrición',t:'Circunferencia de cintura e índice cintura-talla',s:'Obesidad abdominal',f:[n('cin','Circunferencia de cintura','centímetros'),TALLA,SEXO],
  r:v=>{const lim=v.sexo==='H'?90:80,ict=v.cin/v.talla;return{n:v.cin>=lim?'Obesidad abdominal':'Sin obesidad abdominal',u:`Índice cintura-talla ${r2(ict)}`,i:`Punto de corte en México: ${lim} centímetros en ${v.sexo==='H'?'hombres':'mujeres'}. Un índice cintura-talla de 0.5 o más indica riesgo cardiometabólico.`,c:v.cin>=lim||ict>=0.5?'warn':'ok'}},
  ref:['Secretaría de Salud. Norma Oficial Mexicana NOM-008-SSA3-2017, Para el tratamiento integral del sobrepeso y la obesidad. Diario Oficial de la Federación; 2018.','Ashwell M, Gunn P, Gibson S. Waist-to-height ratio is a better screening tool than waist circumference and BMI for adult cardiometabolic risk factors. Obes Rev. 2012;13(3):275-286.']});
add(esc('mnasf','Nutrición','Mini evaluación nutricional, forma corta','Adultos mayores',[
  s('a','Disminución de la ingesta en los últimos 3 meses',[['Grave',0],['Moderada',1],['Sin disminución',2]]),s('b','Pérdida de peso en los últimos 3 meses',[['Mayor de 3 kilogramos',0],['No sabe',1],['1 a 3 kilogramos',2],['Sin pérdida',3]]),s('c','Movilidad',[['Cama o sillón',0],['Se levanta pero no sale',1],['Sale del domicilio',2]]),s('d','Estrés psicológico o enfermedad aguda en los últimos 3 meses',[['Sí',0],['No',2]]),s('e','Problemas neuropsicológicos',[['Demencia o depresión grave',0],['Demencia leve',1],['Sin problemas',2]]),s('f','Índice de masa corporal (o circunferencia de pantorrilla)',[['Menor de 19 (o pantorrilla menor de 31 centímetros)',0],['19 a 20',1],['21 a 22',2],['23 o más (o pantorrilla de 31 o más)',3]])],
  [[7,'0 a 7: desnutrición','bad'],[11,'8 a 11: riesgo de desnutrición','warn'],[14,'12 a 14: estado nutricional normal','ok']],
  ['Kaiser MJ, Bauer JM, Ramsch C, et al. Validation of the Mini Nutritional Assessment short-form (MNA-SF). J Nutr Health Aging. 2009;13(9):782-788.']));

/* LABORATORIO */
add({id:'ldl',c:'Laboratorio',t:'Colesterol de lipoproteínas de baja densidad calculado',s:'Fórmula de Friedewald y colesterol no unido a lipoproteínas de alta densidad',f:[n('ct','Colesterol total','miligramos por decilitro'),n('hdl','Colesterol de lipoproteínas de alta densidad','miligramos por decilitro'),n('tg','Triglicéridos','miligramos por decilitro')],
  r:v=>{const nh=v.ct-v.hdl;if(v.tg>=400)return{n:'No se puede calcular',u:'',i:`Con triglicéridos de 400 o más, Friedewald no es válida: mide directamente. Colesterol no unido a lipoproteínas de alta densidad: ${r0(nh)}.`,c:'warn'};const x=v.ct-v.hdl-v.tg/5;return{n:r0(x),u:'miligramos por decilitro',i:`Colesterol no unido a lipoproteínas de alta densidad: ${r0(nh)} miligramos por decilitro.`,c:x>=190?'bad':x>=130?'warn':'ok',d:'La meta depende del riesgo cardiovascular del paciente.'}},
  ref:['Friedewald WT, Levy RI, Fredrickson DS. Estimation of the concentration of low-density lipoprotein cholesterol in plasma, without use of the preparative ultracentrifuge. Clin Chem. 1972;18(6):499-502.']});
add({id:'mentzer',c:'Laboratorio',t:'Índice de Mentzer',s:'Anemia microcítica: talasemia o ferropenia',f:[n('vcm','Volumen corpuscular medio','femtolitros'),n('gr','Eritrocitos','millones por microlitro')],
  r:v=>{const x=v.vcm/v.gr;return{n:r1(x),u:'',i:x<13?'Menor de 13: sugiere rasgo talasémico':'Mayor de 13: sugiere deficiencia de hierro',c:''}},
  ref:['Mentzer WC Jr. Differentiation of iron deficiency from thalassaemia trait. Lancet. 1973;1(7808):882.']});
add({id:'reti',c:'Laboratorio',t:'Reticulocitos corregidos e índice de producción',s:'',f:[n('ret','Reticulocitos','por ciento'),n('hto','Hematocrito','por ciento')],
  r:v=>{const cor=v.ret*v.hto/45,f=v.hto>=40?1:v.hto>=30?1.5:v.hto>=20?2:2.5,ipr=cor/f;return{n:r2(ipr),u:'índice de producción de reticulocitos',i:ipr<2?'Menor de 2: respuesta medular inadecuada (hipoproliferativa)':'2 o más: respuesta adecuada (hemólisis o sangrado)',c:'',d:`Reticulocitos corregidos ${r2(cor)}%.`}},
  ref:['Hillman RS, Finch CA. Erythropoiesis: normal and abnormal. Semin Hematol. 1967;4(4):327-336.']});
add({id:'light',c:'Laboratorio',t:'Criterios de Light',s:'Derrame pleural: exudado o trasudado',f:[n('pp','Proteínas en líquido pleural','gramos por decilitro'),n('ps','Proteínas séricas','gramos por decilitro'),n('dp','Deshidrogenasa láctica pleural','unidades por litro'),n('ds','Deshidrogenasa láctica sérica','unidades por litro'),n('lsn','Límite superior normal de la deshidrogenasa láctica sérica','unidades por litro')],
  r:v=>{const a=v.pp/v.ps>0.5,b=v.dp/v.ds>0.6,cc=v.dp>2/3*v.lsn;const x=a||b||cc;return{n:x?'Exudado':'Trasudado',u:'',i:`Proteínas ${r2(v.pp/v.ps)}${a?' (mayor de 0.5)':''}; deshidrogenasa ${r2(v.dp/v.ds)}${b?' (mayor de 0.6)':''}; pleural ${cc?'mayor':'menor'} de dos tercios del límite superior.`,c:x?'warn':'ok'}},
  ref:['Light RW, Macgregor MI, Luchsinger PC, Ball WC Jr. Pleural effusions: the diagnostic separation of transudates and exudates. Ann Intern Med. 1972;77(4):507-513.']});
add({id:'sattf',c:'Laboratorio',t:'Saturación de transferrina',s:'',f:[n('fe','Hierro sérico','microgramos por decilitro'),n('ctfh','Capacidad total de fijación de hierro','microgramos por decilitro')],
  r:v=>{const x=v.fe/v.ctfh*100;return{n:r0(x)+'%',u:'',i:x<20?'Menor de 20%: sugiere deficiencia de hierro':x>45?'Mayor de 45%: valorar sobrecarga de hierro':'Normal',c:x<20||x>45?'warn':'ok'}},
  ref:['Camaschella C. Iron-deficiency anemia. N Engl J Med. 2015;372(19):1832-1843.']});
add({id:'can',c:'Laboratorio',t:'Cuenta absoluta de neutrófilos',s:'',f:[n('leu','Leucocitos','por microlitro'),n('seg','Segmentados','por ciento'),n('ban','Bandas','por ciento',{opt:1})],
  r:v=>{const x=v.leu*(v.seg+(v.ban||0))/100;return{n:r0(x),u:'neutrófilos por microlitro',i:x<500?'Neutropenia grave (menor de 500)':x<1000?'Neutropenia moderada (500 a 999)':x<1500?'Neutropenia leve (1000 a 1499)':'Normal',c:x<500?'bad':x<1500?'warn':'ok'}},
  ref:['Newburger PE, Dale DC. Evaluation and management of patients with isolated neutropenia. Semin Hematol. 2013;50(3):198-206.']});

/* CONVERSORES */
const LAB=[['Glucosa: miligramos por decilitro a milimoles por litro',0.0555,'milimoles por litro'],['Creatinina: miligramos por decilitro a micromoles por litro',88.4,'micromoles por litro'],['Nitrógeno ureico a urea (miligramos por decilitro)',2.14,'miligramos por decilitro de urea'],['Urea: miligramos por decilitro a milimoles por litro',0.1665,'milimoles por litro'],['Colesterol: miligramos por decilitro a milimoles por litro',0.02586,'milimoles por litro'],['Triglicéridos: miligramos por decilitro a milimoles por litro',0.01129,'milimoles por litro'],['Calcio: miligramos por decilitro a milimoles por litro',0.2495,'milimoles por litro'],['Bilirrubina: miligramos por decilitro a micromoles por litro',17.1,'micromoles por litro'],['Ácido úrico: miligramos por decilitro a micromoles por litro',59.48,'micromoles por litro'],['Magnesio: miligramos por decilitro a milimoles por litro',0.4114,'milimoles por litro'],['Fósforo: miligramos por decilitro a milimoles por litro',0.3229,'milimoles por litro'],['Hemoglobina: gramos por decilitro a gramos por litro',10,'gramos por litro']];
add({id:'convlab',c:'Conversores',t:'Unidades de laboratorio',s:'Unidades convencionales e internacionales',f:[s('a','Conversión',LAB.map((x,i)=>[x[0],i])),n('x','Valor',''),s('dir','Sentido',[['Convencional a internacional',1],['Internacional a convencional',-1]])],
  r:v=>{const L=LAB[v.a];const y=v.dir===1?v.x*L[1]:v.x/L[1];return{n:(Math.abs(y)<10?Math.round(y*100)/100:r1(y)),u:v.dir===1?L[2]:'en unidades convencionales',i:'Factor '+L[1],c:''}},
  ref:['Young DS. Implementation of SI units for clinical laboratory data. Ann Intern Med. 1987;106(1):114-129.']});
add({id:'convcorp',c:'Conversores',t:'Peso, talla y temperatura',s:'',f:[s('a','Conversión',[['Libras a kilogramos',0],['Kilogramos a libras',1],['Pulgadas a centímetros',2],['Centímetros a pulgadas',3],['Grados Fahrenheit a Celsius',4],['Grados Celsius a Fahrenheit',5]]),n('x','Valor','')],
  r:v=>{const f=[x=>x*0.4536,x=>x/0.4536,x=>x*2.54,x=>x/2.54,x=>(x-32)*5/9,x=>x*9/5+32][v.a],u=['kilogramos','libras','centímetros','pulgadas','grados Celsius','grados Fahrenheit'][v.a];return{n:r1(f(v.x)),u,i:'',c:''}},
  ref:['Oficina Internacional de Pesas y Medidas. El Sistema Internacional de Unidades. 9.ª edición; 2019.']});
add({id:'goteo',c:'Conversores',t:'Goteo e infusiones',s:'Mililitros por hora, gotas por minuto e infusión por peso',f:[s('modo','Cálculo',[['Volumen y tiempo a goteo',0],['Infusión en microgramos por kilo por minuto a mililitros por hora',1]]),
  n('vol','Volumen total','mililitros',{if:v=>v.modo===0}),n('hrs','Tiempo','horas',{if:v=>v.modo===0}),s('eq','Equipo',[['Normogotero (20 gotas por mililitro)',20],['Microgotero (60 microgotas por mililitro)',60]],{if:v=>v.modo===0}),
  n('dosis','Dosis','microgramos por kilo por minuto',{if:v=>v.modo===1}),n('peso','Peso','kilogramos',{if:v=>v.modo===1,pk:'peso'}),n('mg','Fármaco en la mezcla','miligramos',{if:v=>v.modo===1}),n('ml','Volumen de la mezcla','mililitros',{if:v=>v.modo===1})],
  r:v=>{if(v.modo===0){const mlh=v.vol/v.hrs,g=mlh*v.eq/60;return{n:r1(mlh)+' mililitros por hora',u:`${r0(g)} ${v.eq===60?'microgotas':'gotas'} por minuto`,i:'',c:''}}const conc=v.mg*1000/v.ml,mlh=v.dosis*v.peso*60/conc;return{n:r1(mlh)+' mililitros por hora',u:`Concentración ${r1(conc)} microgramos por mililitro`,i:'Verifica la dilución estándar de tu unidad y doble verificación antes de iniciar.',c:''}},
  ref:['Fórmulas de cálculo de dosis por infusión: Institute for Safe Medication Practices. Guidelines for Safe Preparation of Compounded Sterile Preparations; 2016.']});

/* INTERPRETADORES */
add({id:'gaso',c:'Interpretadores',t:'Gasometría arterial',s:'Trastorno primario, compensación y brecha aniónica',f:[n('ph','pH',''),n('pco2','Presión arterial de dióxido de carbono','milímetros de mercurio'),n('hco3','Bicarbonato','miliequivalentes por litro'),n('na','Sodio (opcional)','miliequivalentes por litro',{opt:1}),n('cl','Cloro (opcional)','miliequivalentes por litro',{opt:1}),n('alb','Albúmina (opcional)','gramos por decilitro',{opt:1}),s('t','Evolución si es respiratorio',[['Aguda',0],['Crónica',1]],{opt:1})],
  r:v=>{const{ph,pco2,hco3}=v;const out=[];let tit='',cc='warn';
    if(ph<7.35){if(hco3<22&&pco2<=45){tit='Acidosis metabólica';const e=1.5*hco3+8;out.push(`Presión de dióxido de carbono esperada por Winter ${r1(e-2)} a ${r1(e+2)}: `+(pco2>e+2?'hay acidosis respiratoria agregada':pco2<e-2?'hay alcalosis respiratoria agregada':'compensación adecuada'))}
      else if(pco2>45&&hco3>=22){tit='Acidosis respiratoria';const e=24+(v.t===1?0.35:0.1)*(pco2-40);out.push(`Bicarbonato esperado (${v.t===1?'crónica':'aguda'}) ${r1(e)}: `+(hco3>e+2?'hay alcalosis metabólica agregada':hco3<e-2?'hay acidosis metabólica agregada':'compensación adecuada'))}
      else{tit='Acidosis mixta, metabólica y respiratoria'};cc='bad'}
    else if(ph>7.45){if(hco3>26&&pco2>=35){tit='Alcalosis metabólica';const e=0.7*hco3+21;out.push(`Presión de dióxido de carbono esperada ${r1(e-2)} a ${r1(e+2)}: `+(pco2>e+2?'hay acidosis respiratoria agregada':pco2<e-2?'hay alcalosis respiratoria agregada':'compensación adecuada'))}
      else if(pco2<35&&hco3<=26){tit='Alcalosis respiratoria';const e=24-(v.t===1?0.4:0.2)*(40-pco2);out.push(`Bicarbonato esperado (${v.t===1?'crónica':'aguda'}) ${r1(e)}: `+(hco3>e+2?'hay alcalosis metabólica agregada':hco3<e-2?'hay acidosis metabólica agregada':'compensación adecuada'))}
      else tit='Alcalosis mixta';cc='bad'}
    else{tit=(hco3<22||pco2>45||hco3>26||pco2<35)?'pH normal con valores alterados: posible trastorno mixto':'Gasometría sin alteración ácido-base';cc=tit.startsWith('Gaso')?'ok':'warn'}
    if(v.na&&v.cl){const ag=v.na-(v.cl+hco3),agc=v.alb?ag+2.5*(4-v.alb):ag;out.push(`Brecha aniónica ${r1(ag)}${v.alb?`, corregida ${r1(agc)}`:''}${agc>12?' (elevada)':''}`);if(agc>12&&hco3<24){const dd=(agc-12)/(24-hco3);out.push(`Delta-delta ${r2(dd)}: `+(dd<1?'acidosis con brecha normal agregada':dd>2?'alcalosis metabólica agregada':'acidosis con brecha elevada pura'))}}
    return{n:tit,u:`pH ${ph}, presión de dióxido de carbono ${pco2}, bicarbonato ${hco3}`,i:out.join('. ')||'',c:cc,d:'A nivel del mar. En altitud la presión de dióxido de carbono normal es más baja.'}},
  ref:['Berend K, de Vries AP, Gans RO. Physiological approach to assessment of acid-base disturbances. N Engl J Med. 2014;371(15):1434-1445.','Albert MS, Dell RB, Winters RW. Quantitative displacement of acid-base equilibrium in metabolic acidosis. Ann Intern Med. 1967;66(2):312-322.']});

/* EPIDEMIOLOGÍA */
add({id:'2x2',c:'Epidemiología',t:'Prueba diagnóstica: tabla de 2 por 2',s:'Sensibilidad, especificidad, valores predictivos y razones de verosimilitud',f:[n('a','Verdaderos positivos',''),n('b','Falsos positivos',''),n('c','Falsos negativos',''),n('d','Verdaderos negativos','')],
  r:v=>{const se=v.a/(v.a+v.c),es=v.d/(v.b+v.d),vpp=v.a/(v.a+v.b),vpn=v.d/(v.c+v.d),lrp=se/(1-es),lrn=(1-se)/es,p=(v.a+v.c)/(v.a+v.b+v.c+v.d);const P=x=>isFinite(x)?r1(x*100)+'%':'—';
    return{n:`Sensibilidad ${P(se)}, especificidad ${P(es)}`,u:`Prevalencia en la muestra ${P(p)}`,i:`Valor predictivo positivo ${P(vpp)}; negativo ${P(vpn)}. Razón de verosimilitud positiva ${isFinite(lrp)?r2(lrp):'infinita'}; negativa ${r2(lrn)}.`,c:''}},
  ref:['Altman DG, Bland JM. Diagnostic tests 1: sensitivity and specificity. BMJ. 1994;308(6943):1552.','Deeks JJ, Altman DG. Diagnostic tests 4: likelihood ratios. BMJ. 2004;329(7458):168-169.']});
add({id:'bayes',c:'Epidemiología',t:'Probabilidad posprueba',s:'Teorema de Bayes con razón de verosimilitud',f:[n('pre','Probabilidad previa','por ciento'),n('lr','Razón de verosimilitud','')],
  r:v=>{const o=v.pre/100/(1-v.pre/100),po=o*v.lr,p=po/(1+po);return{n:r1(p*100)+'%',u:'probabilidad posprueba',i:v.lr>10?'Razón mayor de 10: cambio grande, confirma':v.lr<0.1?'Razón menor de 0.1: cambio grande, descarta':'',c:''}},
  ref:['Deeks JJ, Altman DG. Diagnostic tests 4: likelihood ratios. BMJ. 2004;329(7458):168-169.']});
add({id:'nnt',c:'Epidemiología',t:'Número necesario a tratar y medidas de efecto',s:'',f:[n('rc','Riesgo en el grupo control','por ciento'),n('rt','Riesgo en el grupo tratado','por ciento')],
  r:v=>{const rar=(v.rc-v.rt)/100,rr=v.rt/v.rc,rrr=1-rr;return{n:rar!==0?(rar>0?'Número necesario a tratar ':'Número necesario para dañar ')+Math.ceil(Math.abs(1/rar)):'Sin diferencia',u:'',i:`Reducción absoluta del riesgo ${r1(rar*100)}%; riesgo relativo ${r2(rr)}; reducción relativa del riesgo ${r1(rrr*100)}%.`,c:''}},
  ref:['Laupacis A, Sackett DL, Roberts RS. An assessment of clinically useful measures of the consequences of treatment. N Engl J Med. 1988;318(26):1728-1733.']});

